    const overwritesByKey = await this.resourceOverwritesService.getResourceOverwritesAsync(request.context, cancellationToken);
    const solutionResourcesByKey = new Map;
    const fpsKeyBySolutionKey = new Map;
    const identifiersByService = new Map;
