    spec[WellKnownPropertyNames.Name] = resource.name;
    const rootFolder = solution.folders?.[0];
    if (rootFolder && resourceMetadataVersion.scope !== types_ResourceScope.Tenant)
      resource.folders.push({
        fullyQualifiedName: rootFolder.fullyQualifiedName
      });
    solution.resources.push(resource);
    await command.context.saveChangesAsync(cancellationToken);
